/* 0051: CHECK(sizeof c99_long_literal == 4096);
 *
 * monolithic.c:9553 (limits)
 */

#include <stdio.h>

static const char c99_long_literal[] =
    "";

#define CHECK(...)                                                            \
    do {                                                                      \
        if (!(__VA_ARGS__)) {                                                 \
            printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #__VA_ARGS__);      \
            return 1;                                                         \
        }                                                                     \
    } while (0)

int main(void)
{
    CHECK(sizeof c99_long_literal == 4096);
    return 0;
}
